import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, get_index_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
last_decision = None


def load_factors():
    try:
        x = json.loads(ENSEMBLE.read_text(encoding="utf-8"))
        return x.get("selected_factors", [])[:10]
    except Exception:
        return []


def ranks(values):
    good = sorted((s, v) for s, v in values.items() if np.isfinite(v))
    out = {s: .5 for s in UNIVERSE}
    if not good:
        return out
    for i, (s, _) in enumerate(good):
        out[s] = (i + .5) / len(good)
    return out


def bounded_weights(raw):
    # 2% floor and 14% cap, with iterative simplex projection.
    w = {s: max(float(raw.get(s, 1.0)), 1e-10) for s in UNIVERSE}
    fixed = {}
    for _ in range(20):
        free = [s for s in UNIVERSE if s not in fixed]
        rem = 1.0 - sum(fixed.values())
        z = sum(w[s] for s in free)
        for s in free:
            w[s] = rem * w[s] / z
        changed = False
        for s in free:
            if w[s] < .02:
                fixed[s] = .02; changed = True
            elif w[s] > .14:
                fixed[s] = .14; changed = True
        if not changed: break
    z = sum(w.values())
    return {s: w[s] / z for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
